shaderSource:
uniform float2 resolution;
uniform float2 touch;
uniform float time;

float bell(float value, float center, float width) {
  float d = (value - center) / max(width, 0.0001);
  return exp(-d * d);
}

half4 main(float2 xy) {
  float2 safeResolution = max(resolution, float2(1.0));
  float2 uv = xy / safeResolution;
  float aspect = safeResolution.x / safeResolution.y;
  float2 touchUv = clamp(touch / safeResolution, float2(0.0), float2(1.0));

  float2 edgeDistance = min(uv, float2(1.0) - uv);
  float edge = min(edgeDistance.x * aspect, edgeDistance.y);
  float outerRim = 1.0 - smoothstep(0.0, 0.035, edge);
  float innerRim = smoothstep(0.018, 0.065, edge) * (1.0 - smoothstep(0.065, 0.145, edge));
  float topLens = bell(uv.y, 0.045, 0.038) * smoothstep(0.03, 0.18, uv.x) * (1.0 - smoothstep(0.82, 0.97, uv.x));
  float leftLens = bell(uv.x, 0.035, 0.028) * smoothstep(0.05, 0.22, uv.y) * (1.0 - smoothstep(0.78, 0.96, uv.y));
  float lowerShade = smoothstep(0.58, 1.0, uv.y) * smoothstep(0.38, 1.0, uv.x);

  float2 touchDelta = (uv - touchUv) * float2(aspect, 1.0);
  float touchBloom = exp(-dot(touchDelta, touchDelta) * 15.0);
  float touchStreak = exp(-pow(touchDelta.x * 2.0 + touchDelta.y * 0.5, 2.0) * 32.0);
  touchStreak *= exp(-length(touchDelta) * 2.6);
  float slowCaustic = pow(0.5 + 0.5 * sin(uv.x * 7.0 + uv.y * 3.8 + time * 0.28), 5.0);

  half3 color = half3(0.985, 0.992, 1.0);
  color += half3(1.0) * (outerRim * 0.54 + topLens * 0.42 + leftLens * 0.18);
  color += half3(0.92, 0.97, 1.0) * (innerRim * 0.16 + touchBloom * 0.08 + touchStreak * 0.30);
  color += half3(0.96, 0.985, 1.0) * slowCaustic * 0.025;
  color *= 1.0 - lowerShade * 0.10;

  float alpha = 0.035 + outerRim * 0.21 + innerRim * 0.055;
  alpha += topLens * 0.10 + leftLens * 0.045 + touchStreak * 0.075 + touchBloom * 0.025;
  alpha += slowCaustic * 0.012;
  alpha = clamp(alpha, 0.0, 0.38);
  return half4(clamp(color, half3(0.0), half3(1.0)) * half(alpha), half(alpha));
}
